#include <stdlib.h>
typedef struct{int n,*bit,*a;}NumArray;static void add(NumArray*x,int i,int d){for(i++;i<=x->n;i+=i&-i)x->bit[i]+=d;}NumArray* numArrayCreate(int*a,int n){NumArray*x=malloc(sizeof(*x));x->n=n;x->bit=calloc(n+1,sizeof(int));x->a=malloc(n*sizeof(int));for(int i=0;i<n;i++){x->a[i]=a[i];add(x,i,a[i]);}return x;}void numArrayUpdate(NumArray*x,int i,int v){int d=v-x->a[i];x->a[i]=v;add(x,i,d);}static int sum(NumArray*x,int i){int r=0;for(i++;i>0;i-=i&-i)r+=x->bit[i];return r;}int numArraySumRange(NumArray*x,int l,int r){return sum(x,r)-(l?sum(x,l-1):0);}void numArrayFree(NumArray*x){free(x->bit);free(x->a);free(x);}
